def get_max_sum(n, memo={}):
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    result = max(get_max_sum(n // 2, memo) + get_max_sum(n // 3, memo) + get_max_sum(n // 4, memo) + get_max_sum(n // 5, memo), n)
    memo[n] = result
    return result

